"""Roman numerals for 1..3999."""

_PAIRS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
    (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]


def to_roman(n):
    """Return the upper-case numeral for an integer 1..3999."""
    if not isinstance(n, int) or isinstance(n, bool) or not 1 <= n <= 3999:
        raise ValueError(f"cannot convert {n!r}: expected an integer from 1 to 3999")
    out = []
    for value, sym in _PAIRS:
        while n >= value:
            out.append(sym)
            n -= value
    return "".join(out)


def from_roman(s):
    """Return the integer for a canonical upper-case numeral; anything else raises ValueError."""
    if not isinstance(s, str) or not s:
        raise ValueError(f"invalid roman numeral: {s!r}")
    total, i = 0, 0
    for value, sym in _PAIRS:
        while s.startswith(sym, i):
            total += value
            i += len(sym)
    if i != len(s) or total > 3999 or to_roman(total) != s:
        raise ValueError(f"invalid roman numeral: {s!r}")
    return total
